-- Mohalla schema for Supabase Postgres. GENERATED by `python -m app.scripts.dump_schema` from backend/app/models.py.
-- Apply in the Supabase SQL editor (or psql), then supabase/rls.sql. Alternatively `python -m app.scripts.init_db`
-- with DATABASE_URL pointing at Supabase creates the same tables.
-- Money is integer paise. profiles.id = auth.users.id for real users (no FK, so seeded demo profiles also work).

CREATE TABLE IF NOT EXISTS chain_txs (
	id BIGSERIAL NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	ref JSON NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	tx_hash VARCHAR(66), 
	error TEXT, 
	attempts INTEGER NOT NULL, 
	depends_on BIGINT, 
	next_attempt_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS ix_chain_txs_status ON chain_txs (status);

CREATE TABLE IF NOT EXISTS demo_snapshots (
	id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	meta JSON NOT NULL, 
	data JSON NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS distributors (
	id UUID NOT NULL, 
	key VARCHAR(24) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	coverage_h3 JSON NOT NULL, 
	categories JSON NOT NULL, 
	wallet_index INTEGER NOT NULL, 
	wallet_address VARCHAR(42) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (key), 
	UNIQUE (wallet_index)
);

CREATE TABLE IF NOT EXISTS merchants (
	id UUID NOT NULL, 
	shop_no INTEGER NOT NULL, 
	name VARCHAR(160) NOT NULL, 
	owner_name VARCHAR(120) NOT NULL, 
	category VARCHAR(24) NOT NULL, 
	lat FLOAT NOT NULL, 
	lng FLOAT NOT NULL, 
	h3_r8 VARCHAR(20) NOT NULL, 
	h3_r7 VARCHAR(20) NOT NULL, 
	area_name VARCHAR(80) NOT NULL, 
	lang VARCHAR(4) NOT NULL, 
	wallet_index INTEGER NOT NULL, 
	wallet_address VARCHAR(42) NOT NULL, 
	wallet_balance_paise BIGINT NOT NULL, 
	seed_balance_paise BIGINT NOT NULL, 
	base_daily_paise BIGINT NOT NULL, 
	sales_stability FLOAT NOT NULL, 
	onboarded_on DATE NOT NULL, 
	is_demo BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (shop_no), 
	UNIQUE (wallet_index)
);
CREATE INDEX IF NOT EXISTS ix_merchants_h3_r7 ON merchants (h3_r7);
CREATE INDEX IF NOT EXISTS ix_merchants_h3_r8 ON merchants (h3_r8);

CREATE TABLE IF NOT EXISTS skus (
	id UUID NOT NULL, 
	code VARCHAR(40) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	name_hi VARCHAR(80) NOT NULL, 
	category VARCHAR(24) NOT NULL, 
	case_size INTEGER NOT NULL, 
	case_price_paise INTEGER NOT NULL, 
	unit_retail_paise INTEGER NOT NULL, 
	sku_share FLOAT NOT NULL, 
	emoji VARCHAR(16) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);

CREATE TABLE IF NOT EXISTS trust_scores (
	subject_address VARCHAR(42) NOT NULL, 
	subject_type VARCHAR(12) NOT NULL, 
	merchant_id UUID, 
	score INTEGER NOT NULL, 
	components JSON NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (subject_address)
);
CREATE INDEX IF NOT EXISTS ix_trust_scores_merchant_id ON trust_scores (merchant_id);

CREATE TABLE IF NOT EXISTS category_mix (
	merchant_id UUID NOT NULL, 
	category VARCHAR(24) NOT NULL, 
	share FLOAT NOT NULL, 
	PRIMARY KEY (merchant_id, category), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);

CREATE TABLE IF NOT EXISTS daily_sales (
	merchant_id UUID NOT NULL, 
	day DATE NOT NULL, 
	txn_count INTEGER NOT NULL, 
	amount_paise BIGINT NOT NULL, 
	unique_payers INTEGER NOT NULL, 
	PRIMARY KEY (merchant_id, day), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);

CREATE TABLE IF NOT EXISTS forecasts (
	merchant_id UUID NOT NULL, 
	category VARCHAR(24) NOT NULL, 
	window_start DATE NOT NULL, 
	window_end DATE NOT NULL, 
	p10 BIGINT NOT NULL, 
	p50 BIGINT NOT NULL, 
	p90 BIGINT NOT NULL, 
	uplift FLOAT NOT NULL, 
	reason JSON NOT NULL, 
	model VARCHAR(40) NOT NULL, 
	PRIMARY KEY (merchant_id, category, window_start), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);

CREATE TABLE IF NOT EXISTS inventory (
	merchant_id UUID NOT NULL, 
	sku_id UUID NOT NULL, 
	qty_units INTEGER NOT NULL, 
	seed_qty_units INTEGER NOT NULL, 
	source VARCHAR(16) NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (merchant_id, sku_id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id), 
	FOREIGN KEY(sku_id) REFERENCES skus (id)
);

CREATE TABLE IF NOT EXISTS invoices (
	id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	image_path VARCHAR(300), 
	parsed JSON, 
	status VARCHAR(16) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);

CREATE TABLE IF NOT EXISTS loans (
	id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	pool_id UUID, 
	amount_paise BIGINT NOT NULL, 
	rate_bps INTEGER NOT NULL, 
	tenure_days INTEGER NOT NULL, 
	daily_deduct_bps INTEGER NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	decision JSON NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_loans_merchant_id ON loans (merchant_id);

CREATE TABLE IF NOT EXISTS nudges (
	id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	text_hi TEXT NOT NULL, 
	text_en TEXT NOT NULL, 
	audio_path VARCHAR(300), 
	pool_id UUID, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	heard_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_nudges_merchant_id ON nudges (merchant_id);

CREATE TABLE IF NOT EXISTS pending_actions (
	id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	payload JSON NOT NULL, 
	summary_hi TEXT NOT NULL, 
	summary_en TEXT NOT NULL, 
	idempotency_key VARCHAR(120), 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_pending_actions_merchant_id ON pending_actions (merchant_id);

CREATE TABLE IF NOT EXISTS profiles (
	id UUID NOT NULL, 
	role VARCHAR(16), 
	merchant_id UUID, 
	distributor_id UUID, 
	display_name VARCHAR(120), 
	email VARCHAR(200), 
	lang VARCHAR(4) NOT NULL, 
	dev_token VARCHAR(40), 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id), 
	FOREIGN KEY(distributor_id) REFERENCES distributors (id), 
	UNIQUE (dev_token)
);

CREATE TABLE IF NOT EXISTS schemes (
	id UUID NOT NULL, 
	distributor_id UUID NOT NULL, 
	sku_id UUID NOT NULL, 
	slabs JSON NOT NULL, 
	valid_from DATE NOT NULL, 
	valid_to DATE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(distributor_id) REFERENCES distributors (id), 
	FOREIGN KEY(sku_id) REFERENCES skus (id)
);

CREATE TABLE IF NOT EXISTS transactions (
	id BIGSERIAL NOT NULL, 
	merchant_id UUID NOT NULL, 
	ts TIMESTAMP WITH TIME ZONE NOT NULL, 
	amount_paise INTEGER NOT NULL, 
	payer_hash VARCHAR(32) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_transactions_merchant_id ON transactions (merchant_id);

CREATE TABLE IF NOT EXISTS pools (
	id UUID NOT NULL, 
	chain_id_hex VARCHAR(66) NOT NULL, 
	sku_id UUID NOT NULL, 
	distributor_id UUID NOT NULL, 
	scheme_id UUID, 
	target_cases INTEGER NOT NULL, 
	committed_cases INTEGER NOT NULL, 
	base_case_price_paise INTEGER NOT NULL, 
	case_price_paise INTEGER NOT NULL, 
	disc_bps INTEGER NOT NULL, 
	slabs JSON NOT NULL, 
	center_h3 VARCHAR(20) NOT NULL, 
	cluster_h3 VARCHAR(20), 
	center_lat FLOAT NOT NULL, 
	center_lng FLOAT NOT NULL, 
	area_name VARCHAR(80) NOT NULL, 
	deadline TIMESTAMP WITH TIME ZONE NOT NULL, 
	delivery_deadline TIMESTAMP WITH TIME ZONE NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	create_tx_id BIGINT, 
	chain_deadline BIGINT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	funded_at TIMESTAMP WITH TIME ZONE, 
	settled_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(sku_id) REFERENCES skus (id), 
	FOREIGN KEY(distributor_id) REFERENCES distributors (id), 
	FOREIGN KEY(scheme_id) REFERENCES schemes (id)
);
CREATE INDEX IF NOT EXISTS ix_pools_deadline ON pools (deadline);
CREATE INDEX IF NOT EXISTS ix_pools_status ON pools (status);

CREATE TABLE IF NOT EXISTS deliveries (
	pool_id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	qr_nonce VARCHAR(40) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	confirmed_at TIMESTAMP WITH TIME ZONE, 
	on_time BOOLEAN, 
	payout_paise BIGINT, 
	fee_paise BIGINT, 
	tx_id BIGINT, 
	attestation_uid VARCHAR(66), 
	PRIMARY KEY (pool_id, merchant_id), 
	FOREIGN KEY(pool_id) REFERENCES pools (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);

CREATE TABLE IF NOT EXISTS pool_commitments (
	pool_id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	cases INTEGER NOT NULL, 
	amount_paise BIGINT NOT NULL, 
	loan_id UUID, 
	status VARCHAR(12) NOT NULL, 
	tx_id BIGINT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (pool_id, merchant_id), 
	FOREIGN KEY(pool_id) REFERENCES pools (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_commitments_merchant ON pool_commitments (merchant_id);

CREATE TABLE IF NOT EXISTS pool_invites (
	pool_id UUID NOT NULL, 
	merchant_id UUID NOT NULL, 
	suggested_cases INTEGER NOT NULL, 
	reason JSON NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (pool_id, merchant_id), 
	FOREIGN KEY(pool_id) REFERENCES pools (id), 
	FOREIGN KEY(merchant_id) REFERENCES merchants (id)
);
CREATE INDEX IF NOT EXISTS ix_invites_merchant ON pool_invites (merchant_id);

